INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is ''sulphur dye'' commonly used for, and what is a notable characteristic of its application?', '["Dyeing cotton (especially in dark shades like black/navy) economically; it requires reduction (similar to vat dye) to become soluble before application","Dyeing only synthetic polyester fiber using high-temperature methods","A dye applied without any chemical treatment, used purely for pastel shades","A dye that only works on protein fibers like wool and silk"]'::jsonb, 'Dyeing cotton (especially in dark shades like black/navy) economically; it requires reduction (similar to vat dye) to become soluble before application', 'Sulphur dyes are popular for economical dark-shade cotton dyeing (black, navy, brown); like vat dyes, they must be chemically reduced to a soluble form for fiber penetration, then oxidized back to an insoluble, fixed colored form within the fiber.', 2, '{"sulphur-dye"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is ''metamerism'' as it relates to dyed fabric color?', '["Two dyed samples appearing to match in color under one light source but appearing different under another light source","A fabric changing color permanently after washing","The exact chemical formula of a dye molecule","A defect where dye fails to penetrate the fiber at all"]'::jsonb, 'Two dyed samples appearing to match in color under one light source but appearing different under another light source', 'Metamerism occurs when two samples (often dyed with different dye combinations) reflect light differently across the spectrum in a way that happens to match under one illuminant (e.g., daylight) but mismatch under another (e.g., store fluorescent lighting) — a common practical dyeing/shade-matching challenge.', 2, '{"metamerism"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why is checking shade match under MULTIPLE light sources (e.g., daylight, tungsten, fluorescent) considered important quality practice, rather than checking under just one?', '["A shade might match acceptably under one light source but reveal a mismatch (metamerism) under another, which could be a customer''s actual usage/retail environment","Light source has no effect whatsoever on how a dyed fabric''s color appears","Checking under multiple lights is purely a formality with no practical benefit","Only daylight matters; other light sources are never relevant to textile quality"]'::jsonb, 'A shade might match acceptably under one light source but reveal a mismatch (metamerism) under another, which could be a customer''s actual usage/retail environment', 'Because metameric matches can look fine under one light but mismatched under another, checking multiple relevant light sources (daylight, standard indoor lighting, etc.) helps catch potential real-world color complaints before the product reaches the customer.', 2, '{"metamerism","shade-checking"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What does ''K/S value'' represent in computer color matching (CCM) for dyeing recipe prediction?', '["A mathematical relationship (from the Kubelka-Munk theory) between a dye''s absorption and scattering coefficients, used to relate dye concentration to color strength","The exact temperature used during the dyeing process","The total weight of fabric being dyed in a batch","The pH level of the dye bath"]'::jsonb, 'A mathematical relationship (from the Kubelka-Munk theory) between a dye''s absorption and scattering coefficients, used to relate dye concentration to color strength', 'K/S (Kubelka-Munk function) relates a dyed sample''s light absorption (K) and scattering (S) properties to dye concentration, forming the mathematical basis computer color matching software uses to predict dye recipes for a target shade.', 2, '{"k-s-value","computer-color-matching"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is the basic purpose of computer color matching (CCM) software in a dye house?', '["To predict a dye recipe (which dyes and how much of each) needed to achieve a target shade, reducing costly trial-and-error lab dips","To physically operate the dyeing machine without any human involvement at all","To replace the need for any dye chemicals whatsoever","To measure only the final fabric weight after dyeing"]'::jsonb, 'To predict a dye recipe (which dyes and how much of each) needed to achieve a target shade, reducing costly trial-and-error lab dips', 'CCM software uses spectral data and the K/S relationship to calculate optimal dye combinations/quantities for a target shade before physical dyeing, significantly reducing the number of trial lab dips needed and speeding up recipe development.', 2, '{"computer-color-matching"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is a ''lab dip'' in the dyeing/color-approval process?', '["A small-scale trial dyeing sample produced to check and get approval for a shade before bulk production","The final large-scale bulk dyeing batch itself","A chemical used only for bleaching, unrelated to color matching","A machine used exclusively for fabric finishing, not dyeing"]'::jsonb, 'A small-scale trial dyeing sample produced to check and get approval for a shade before bulk production', 'A lab dip is a small test sample dyed under controlled lab conditions to check if a proposed recipe achieves the target/approved shade; buyers/brands typically must approve a lab dip before the mill proceeds to full bulk production dyeing.', 1, '{"lab-dip"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why is it important that a lab dip''s dyeing conditions (liquor ratio, temperature profile, machine type) closely simulate the actual bulk dyeing process?', '["Dyeing behavior (exhaustion, shade outcome) can vary significantly with process conditions, so a lab dip under different conditions may not accurately predict the bulk result","Lab dip conditions have zero effect on whether bulk dyeing achieves the same shade","Bulk dyeing machines always produce identical results regardless of the lab dip method used","Lab dips are only used for fabric strength testing, not for predicting shade"]'::jsonb, 'Dyeing behavior (exhaustion, shade outcome) can vary significantly with process conditions, so a lab dip under different conditions may not accurately predict the bulk result', 'Since liquor ratio, temperature, and machine type all affect dye exhaustion/behavior, a lab dip conducted under conditions very different from the actual bulk process may show a shade that doesn''t reliably reproduce during bulk dyeing — process similarity is key to a lab dip''s predictive value.', 2, '{"lab-dip","process-simulation"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the general purpose of an ''anti-pilling'' finish or treatment on knitted/woven fabric?', '["To reduce the formation of small fiber balls (pills) on the fabric surface caused by rubbing/wear","To permanently add extra fiber pills to the fabric surface for texture","To remove all color from the fabric","To increase the fabric''s water absorbency to the maximum possible level"]'::jsonb, 'To reduce the formation of small fiber balls (pills) on the fabric surface caused by rubbing/wear', 'Anti-pilling treatments (chemical or through fiber/yarn choice) aim to reduce pilling — the formation of small tangled fiber balls on the fabric surface from rubbing/abrasion during wear — a common complaint especially with certain synthetic and blended fabrics.', 1, '{"anti-pilling-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the purpose of a ''flame retardant'' (FR) finish applied to certain textile products?', '["To reduce the fabric''s flammability and slow flame spread, important for products like children''s sleepwear or industrial workwear","To permanently change the fabric''s base color to a fire-resistant hue","To increase the fabric''s flammability for special effects","To remove all moisture-absorbing properties from the fiber"]'::jsonb, 'To reduce the fabric''s flammability and slow flame spread, important for products like children''s sleepwear or industrial workwear', 'FR finishes (or inherently flame-resistant fibers) reduce how easily a fabric ignites and how fast flame spreads across it — critical for safety-regulated end uses like children''s sleepwear, protective workwear, and certain home furnishings.', 1, '{"flame-retardant-finish"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why must flame-retardant finish durability (surviving repeated washing) be specifically tested and certified for products like children''s sleepwear?', '["An FR finish that washes out over time would leave the garment without its safety protection despite still being marketed/used as flame-resistant","FR finishes never wash out under any circumstances, so durability testing is unnecessary","Washing always improves FR finish performance rather than degrading it","FR performance has no relationship to how many times a garment has been washed"]'::jsonb, 'An FR finish that washes out over time would leave the garment without its safety protection despite still being marketed/used as flame-resistant', 'Since some FR treatments can degrade with repeated laundering, safety regulations for products like children''s sleepwear require the flame-retardant property to be tested and proven durable through a specified number of wash cycles — an untested or non-durable finish could create a false sense of safety.', 2, '{"flame-retardant-durability"}'::text[]);
